/**
 * SPANDANA demonstration data layer.
 *
 * Demo-mode WAVEFORMS and per-upload PREDICTIONS here are still synthetic:
 *  - waveforms are generated by a deterministic mathematical model,
 *  - "predictions" come from a fixed logistic simulator (used only when the
 *    FastAPI backend is offline), NOT from a trained Perceptron or CNN.
 * MODEL_METRICS below are REAL: the measured results on the PTB-XL test set
 * (strat_fold 10), copied from backend/models/metrics.json.
 */

import { computeCriteria, criteriaHeadline } from "@/lib/ecg/criteria";
import { buildProfile, generateWaveform, mulberry32 } from "@/lib/ecg/waveform";
import { buildParsedSpec } from "@/lib/ecg/real-signal";
import type { ParsedSignal } from "@/lib/ecg/parsers";
import {
  type EcgAnalysis,
  type EcgWaveform,
  type Interpretation,
  type ModelPrediction,
  type ParsedSpecData,
  type PatientMeta,
  type Sex,
  type WaveformSpec,
} from "@/lib/ecg/types";

/* ------------------------------------------------------------------ */
/* Simulated AI inference (demo only)                                  */
/* ------------------------------------------------------------------ */

interface FeatureVector {
  sv1: number;
  rv56: number;
  ravl: number;
  sv3: number;
  ageNorm: number;
}

const PERCEPTRON_WEIGHTS = { sv1: 0.64, rv56: 2.12, ravl: 0.85, sv3: 1.06, age: 0.32 };
const PERCEPTRON_BIAS = -8.37;
const CNN_WEIGHTS = { sv1: 0.5, rv56: 1.6, ravl: 1.3, sv3: 1.5, age: 0.25 };
const CNN_BIAS = -7.5;

const sigmoid = (z: number) => 1 / (1 + Math.exp(-z));

function featureVectorOf(
  waveform: EcgWaveform,
  age: number,
  rv56: number,
): FeatureVector {
  return {
    sv1: waveform.amplitudes["V1"].s,
    rv56,
    ravl: waveform.amplitudes["aVL"].r,
    sv3: waveform.amplitudes["V3"].s,
    ageNorm: (age - 50) / 20,
  };
}

function contributionsOf(
  f: FeatureVector,
  w: typeof PERCEPTRON_WEIGHTS,
): { feature: string; weight: number; value: number }[] {
  return [
    { feature: "SV1 (mV)", weight: w.sv1, value: f.sv1 },
    { feature: "RV5/V6 (mV)", weight: w.rv56, value: f.rv56 },
    { feature: "RaVL (mV)", weight: w.ravl, value: f.ravl },
    { feature: "SV3 (mV)", weight: w.sv3, value: f.sv3 },
    { feature: "Age (norm.)", weight: w.age, value: f.ageNorm },
  ].sort((a, b) => Math.abs(b.weight * b.value) - Math.abs(a.weight * a.value));
}

/**
 * Fixed logistic simulator standing in for the real models until the
 * FastAPI backend is connected. Results are flagged `simulated: true`.
 */
export function simulatePredictions(
  seed: string,
  waveform: EcgWaveform,
  age: number,
): ModelPrediction[] {
  const rng = mulberry32(`${seed}::predictions`);
  const rv56 = Math.max(
    waveform.amplitudes["V5"].r,
    waveform.amplitudes["V6"].r,
  );
  const f = featureVectorOf(waveform, age, rv56);

  const zP =
    f.sv1 * PERCEPTRON_WEIGHTS.sv1 +
    f.rv56 * PERCEPTRON_WEIGHTS.rv56 +
    f.ravl * PERCEPTRON_WEIGHTS.ravl +
    f.sv3 * PERCEPTRON_WEIGHTS.sv3 +
    f.ageNorm * PERCEPTRON_WEIGHTS.age +
    PERCEPTRON_BIAS;
  const pP = sigmoid(zP);

  const zC =
    f.sv1 * CNN_WEIGHTS.sv1 +
    f.rv56 * CNN_WEIGHTS.rv56 +
    f.ravl * CNN_WEIGHTS.ravl +
    f.sv3 * CNN_WEIGHTS.sv3 +
    f.ageNorm * CNN_WEIGHTS.age +
    CNN_BIAS;
  const pC = sigmoid(zC);

  const mk = (
    model: ModelPrediction["model"],
    probability: number,
    latency: number,
    weights: typeof PERCEPTRON_WEIGHTS,
  ): ModelPrediction => ({
    model,
    probability: Math.round(probability * 1000) / 1000,
    positive: probability >= 0.5,
    threshold: 0.5,
    latencyMs: latency,
    simulated: true,
    contributions: contributionsOf(f, weights),
  });

  return [
    mk("perceptron", pP, 2 + Math.round(rng() * 6), PERCEPTRON_WEIGHTS),
    mk("cnn", pC, 38 + Math.round(rng() * 95), CNN_WEIGHTS),
  ];
}

/* ------------------------------------------------------------------ */
/* Interpretation                                                      */
/* ------------------------------------------------------------------ */

export function deriveInterpretation(a: {
  criteria: EcgAnalysis["criteria"];
  predictions: ModelPrediction[];
}): Interpretation {
  const headline = criteriaHeadline(a.criteria);
  const aiPositives = a.predictions.filter((p) => p.positive).length;
  const aiAgreePos = a.predictions.length > 0 && aiPositives === a.predictions.length;
  const aiAgreeNeg = a.predictions.length > 0 && aiPositives === 0;

  if (headline === "positive" && aiAgreePos) return "positive";
  if (headline === "negative" && aiAgreeNeg) return "negative";
  return "discordant";
}

/* ------------------------------------------------------------------ */
/* Analysis assembly                                                   */
/* ------------------------------------------------------------------ */

export interface AssembleInput {
  id: string;
  createdAt: string;
  meta: PatientMeta;
  spec: WaveformSpec;
  notes: string;
}

export function assembleAnalysis(input: AssembleInput): EcgAnalysis {
  const waveform = generateWaveform(input.spec);
  const criteria = computeCriteria(waveform, input.meta.sex);
  const predictions = simulatePredictions(input.spec.seed, waveform, input.meta.age);
  return {
    ...input,
    waveform,
    criteria,
    predictions,
    interpretation: deriveInterpretation({ criteria, predictions }),
    isDemoData: true,
  };
}

/* ------------------------------------------------------------------ */
/* Demo library                                                        */
/* ------------------------------------------------------------------ */

export function createDemoAnalyses(now = Date.now()): EcgAnalysis[] {
  const hoursAgo = (h: number) => new Date(now - h * 3600_000).toISOString();

  // DEMO-001 — LVH positive: concordant criteria + lateral strain pattern.
  const spec1: WaveformSpec = {
    seed: "spandana-demo-001",
    bpm: 72,
    profile: buildProfile({
      V1: { s: 1.3 },
      V2: { s: 1.7 },
      V3: { s: 1.9, t: 0.05 },
      V4: { r: 2.6, s: 0.8 },
      V5: { r: 3.0, t: -0.16 },
      V6: { r: 2.45, t: -0.12 },
      aVL: { r: 1.2, t: -0.1 },
      I: { r: 1.05, t: -0.08 },
    }),
  };

  // DEMO-002 — negative: normal voltages across all leads.
  const spec2: WaveformSpec = {
    seed: "spandana-demo-002",
    bpm: 64,
    profile: buildProfile({
      V1: { s: 0.9 },
      V3: { s: 1.1 },
      V5: { r: 1.9 },
      aVL: { r: 0.7 },
    }),
  };

  // DEMO-003 — borderline: Cornell positive, Sokolow–Lyon negative.
  const spec3: WaveformSpec = {
    seed: "spandana-demo-003",
    bpm: 78,
    profile: buildProfile({
      V1: { s: 1.1 },
      V3: { s: 1.9 },
      V5: { r: 1.8 },
      aVL: { r: 1.0 },
    }),
  };

  const demos: AssembleInput[] = [
    {
      id: "demo-001",
      createdAt: hoursAgo(3),
      meta: {
        code: "DEMO-001",
        age: 58,
        sex: "Male",
        source: "demo-library",
        demoLabel: "lvh-positive",
      },
      spec: spec1,
      notes:
        "Curated demonstration recording with concordant positive voltage criteria and a simulated high AI probability. Morphology includes lateral T-wave inversion (I, aVL, V5–V6) consistent with the LVH strain pattern often described in textbooks.",
    },
    {
      id: "demo-002",
      createdAt: hoursAgo(27),
      meta: {
        code: "DEMO-002",
        age: 63,
        sex: "Female",
        source: "demo-library",
        demoLabel: "lvh-negative",
      },
      spec: spec2,
      notes:
        "Curated demonstration recording with normal voltages. Both traditional criteria are negative and the simulated models return low LVH probability.",
    },
    {
      id: "demo-003",
      createdAt: hoursAgo(50),
      meta: {
        code: "DEMO-003",
        age: 45,
        sex: "Male",
        source: "demo-library",
        demoLabel: "borderline",
      },
      spec: spec3,
      notes:
        "Curated borderline demonstration: the Cornell criterion is positive by a narrow 0.05 mV margin while Sokolow–Lyon and both simulated models lean negative. This case illustrates the discordance that motivates multimodal evaluation in the SPANDANA research protocol.",
    },
  ];

  return demos.map(assembleAnalysis);
}

/* ------------------------------------------------------------------ */
/* Decoded-file analysis (real signal, simulated AI)                   */
/* ------------------------------------------------------------------ */

export interface DecodedAnalysisInput {
  fileName: string;
  /** Result of the in-browser decoder (real samples, mV). */
  signal: ParsedSignal;
  sex: Sex;
  age: number;
  code: string;
  /** Index to stagger createdAt between multiple uploads. */
  order?: number;
  /** Pre-computed parsed spec (skips a redundant re-measurement). */
  parsed?: ParsedSpecData;
}

/**
 * Assemble an analysis whose waveform is the REAL signal decoded from the
 * uploaded file. Criteria are computed from real measured voltages; the
 * AI predictions stay in the clearly-labelled simulator until the FastAPI
 * backend runs actual inference.
 */
export function createDecodedAnalysis(input: DecodedAnalysisInput): EcgAnalysis {
  const parsed = input.parsed ?? buildParsedSpec(input.signal);

  const spec: WaveformSpec = {
    seed: `decoded::${input.fileName}::${input.code}`,
    bpm: parsed.bpm,
    profile: buildProfile({}), // unused for parsed specs; keeps the shape uniform
    parsed,
  };

  const offset = (input.order ?? 0) * 2_000;
  const analysis = assembleAnalysis({
    id: `upl-${crypto.randomUUID()}`,
    createdAt: new Date(Date.now() - offset).toISOString(),
    meta: {
      code: input.code,
      age: input.age,
      sex: input.sex,
      source: "file-upload",
      sourceFile: input.fileName,
      signalOrigin: "decoded-file",
      // demoLabel is unused for decoded uploads but kept for shape uniformity.
      demoLabel: "borderline",
    },
    spec,
    notes:
      `Signal decoded in-browser from "${input.fileName}" (${parsed.detail}). ` +
      "Voltage criteria were measured from the decoded samples. All AI outputs remain SIMULATED until the FastAPI research backend runs real inference.",
  });

  return analysis;
}

